import{_ as a,o as n,c as s,a2 as t}from"./chunks/framework.1C62pOns.js";const o="/pro-agent-hub-installer/capturas/es/agentes-detalhe.png",r="/pro-agent-hub-installer/capturas/es/agentes-codigo.png",i="/pro-agent-hub-installer/capturas/es/times-fluxo.png",c="/pro-agent-hub-installer/capturas/es/chat.png",b=JSON.parse('{"title":"Agentes, equipos y chat","description":"","frontmatter":{},"headers":[],"relativePath":"es/interface/agentes.md","filePath":"es/interface/agentes.md","lastUpdated":1787856241000}'),l={name:"es/interface/agentes.md"};function d(p,e,u,g,m,h){return n(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="agentes-equipos-y-chat" tabindex="-1">Agentes, equipos y chat <a class="header-anchor" href="#agentes-equipos-y-chat" aria-label="Permalink to &quot;Agentes, equipos y chat&quot;">​</a></h1><h2 id="agentes" tabindex="-1">Agentes <a class="header-anchor" href="#agentes" aria-label="Permalink to &quot;Agentes&quot;">​</a></h2><p><img src="'+o+'" alt="agentes-detalhe"></p><p>Un <strong>agente</strong> es un modelo con instrucciones, herramientas y, opcionalmente, conocimiento. Es la unidad que conversa y ejecuta.</p><h3 id="pestana-instrucciones" tabindex="-1">Pestaña Instrucciones <a class="header-anchor" href="#pestana-instrucciones" aria-label="Permalink to &quot;Pestaña Instrucciones&quot;">​</a></h3><p>Aquí el agente gana personalidad y límites. Tres campos, con papeles distintos:</p><ul><li><strong>Descripción del agente</strong> — quién es. Va al principio del contexto.</li><li><strong>Instrucción</strong> — cómo debe actuar. Es el campo que más cambia el resultado.</li><li><strong>Salida esperada</strong> — el formato de la respuesta, cuando necesitas algo estructurado.</li></ul><p><strong>Historial</strong>: activar <em>añadir historial al contexto</em> hace que el agente recuerde la conversación. El número de ejecuciones anteriores es lo que carga — más historial cuesta más tokens en cada pregunta.</p><h3 id="pestana-herramientas" tabindex="-1">Pestaña Herramientas <a class="header-anchor" href="#pestana-herramientas" aria-label="Permalink to &quot;Pestaña Herramientas&quot;">​</a></h3><p>Herramientas listas (búsqueda web, Wikipedia, gráficos), servicios MCP vinculados y los conocimientos que puede consultar.</p><p>Un agente puede tener <strong>varios conocimientos</strong>. La búsqueda ocurre en todos, y los fragmentos más cercanos entran en el contexto.</p><h3 id="pestana-codigo" tabindex="-1">Pestaña Código <a class="header-anchor" href="#pestana-codigo" aria-label="Permalink to &quot;Pestaña Código&quot;">​</a></h3><p><img src="'+r+'" alt="agentes-codigo"></p><p>Cada función de nivel superior que escribas aquí se convierte en una herramienta del agente — el modelo decide cuándo llamarla leyendo el nombre y el docstring. Escribe ambos pensando en quien va a leer: el lector es el modelo.</p><div class="danger custom-block"><p class="custom-block-title">Aquí no existe ninguna función de la plataforma</p><p>Este es el único lugar de código de la plataforma que corre en <strong>ámbito vacío</strong>. <code>db_query</code>, <code>send_email</code> y las demás operaciones <strong>no existen</strong> aquí — usarlas da <code>NameError</code>. Usa <code>import</code> para lo que necesites. Ver <a href="/pro-agent-hub-installer/es/funcoes/agente_tool">Agente — código de herramienta</a>.</p></div><h2 id="equipos" tabindex="-1">Equipos <a class="header-anchor" href="#equipos" aria-label="Permalink to &quot;Equipos&quot;">​</a></h2><p><img src="'+i+'" alt="times-fluxo"></p><p>Un <strong>equipo</strong> organiza agentes en una jerarquía: un coordinador que recibe la pregunta y delega en especialistas. Tiene sentido cuando un solo agente acabaría con instrucciones demasiado largas, o cuando cada parte necesita un modelo distinto.</p><p>La pestaña <strong>Flujo</strong> es un lienzo donde montas la jerarquía arrastrando agentes y subequipos. Cada nodo lleva el papel y las instrucciones específicas de ese integrante en ese equipo — el mismo agente puede participar en equipos distintos con papeles distintos.</p><h2 id="chat" tabindex="-1">Chat <a class="header-anchor" href="#chat" aria-label="Permalink to &quot;Chat&quot;">​</a></h2><p><img src="'+c+'" alt="chat"></p><p>La pantalla de conversación. Elige un agente o un equipo y conversa. Acepta adjuntar archivos e imágenes cuando el modelo lo soporta.</p><p>Es también el lugar para probar antes de automatizar: si el agente no responde bien en el chat, no va a responder bien dentro de un workflow.</p>',23)])])}const _=a(l,[["render",d]]);export{b as __pageData,_ as default};
